    "compatibility": "uno",
    "code": "/*\r\n  String Case changes\r\n\r\n  Examples of how to change the case of a String\r\n\r\n  created 27 Jul 2010\r\n  modified 2 Apr 2012\r\n  by Tom Igoe\r\n\r\n  This example code is in the public domain.\r\n\r\n  https://docs.arduino.cc/built-in-examples/strings/StringCaseChanges/\r\n*/\r\n\r\nvoid setup() {\r\n  // Open serial communications and wait for port to open:\r\n  Serial.begin(9600);\r\n  while (!Serial) {\r\n    ;  // wait for serial port to connect. Needed for native USB port only\r\n  }\r\n\r\n  // send an intro:\r\n  Serial.println(\"\\n\\nString case changes:\");\r\n  Serial.println();\r\n}\r\n\r\nvoid loop() {\r\n  // toUpperCase() changes all letters to upper case:\r\n  String stringOne = \"<html><head><body>\";\r\n  Serial.println(stringOne);\r\n  stringOne.toUpperCase();\r\n  Serial.println(stringOne);\r\n\r\n  // toLowerCase() changes all letters to lower case:\r\n  String stringTwo = \"</BODY></HTML>\";\r\n  Serial.println(stringTwo);\r\n  stringTwo.toLowerCase();\r\n  Serial.println(stringTwo);\r\n\r\n\r\n  // do nothing while true:\r\n  while (true)\r\n    ;\r\n}\r\n",
    "sourceUrl": "https://github.com/arduino/arduino-examples/blob/ad14bc44cb95555e5df7c16e6605559cad860d29/examples/08.Strings/StringCaseChanges/StringCaseChanges.ino"
